WITH recent_transactions AS (SELECT * FROM transactions WHERE merchant IN ('Shell', 'Grab', 'Starbucks') AND merchant IN ('Lazada', 'Shell', 'Grab') AND account_id IN (3, 40)), is_flagged_summary AS (SELECT is_flagged, COUNT(DISTINCT amount) AS unique_txn_types FROM recent_transactions GROUP BY is_flagged) SELECT * FROM is_flagged_summary ORDER BY unique_txn_types, is_flagged LIMIT 10
